Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
scsi: bfa: Ensure the copied buf is NUL terminated

Currently, we allocate a nbytes-sized kernel buffer and copy nbytes from
userspace to that buffer. Later, we use sscanf on this buffer but we don't
ensure that the string is terminated inside the buffer, this can lead to
OOB read when using sscanf. Fix this issue by using memdup_user_nul instead
of memdup_user.

Fixes: 9f30b674759b ("bfa: replace 2 kzalloc/copy_from_user by memdup_user")
Signed-off-by: Bui Quang Minh <minhquangbui99@gmail.com>
Link: https://lore.kernel.org/r/20240424-fix-oob-read-v2-3-f1f1b53a10f4@gmail.com
Signed-off-by: Martin K. Petersen <martin.petersen@oracle.com>

Here is the root cause:
The bug arises from the use of `memdup_user` to copy data from user space to a kernel buffer without ensuring that the copied string is null-terminated. This can lead to out-of-bounds reads when the buffer is processed with functions like `sscanf`, which expect a null-terminated string. If the string is not properly terminated, it may read beyond the allocated buffer, potentially causing memory corruption or crashes.

Here is the patch:

 static ssize_t
 bfad_debugfs_write_regrd(struct file *file, const char __user *buf,
 		size_t nbytes, loff_t *ppos)
 {
 	struct bfad_debug_info *regrd_debug = file->private_data;
 	struct bfad_port_s *port = (struct bfad_port_s *)regrd_debug->i_private;
 	struct bfad_s *bfad = port->bfad;
 	struct bfa_s *bfa = &bfad->bfa;
 	struct bfa_ioc_s *ioc = &bfa->ioc;
 	int addr, rc, i;
 	u32 len;
 	u32 *regbuf;
 	void __iomem *rb, *reg_addr;
 	unsigned long flags;
 	void *kern_buf;

-	kern_buf = memdup_user(buf, nbytes);
+	kern_buf = memdup_user_nul(buf, nbytes);
 	if (IS_ERR(kern_buf))
 		return PTR_ERR(kern_buf);

 	rc = sscanf(kern_buf, "%x:%x", &addr, &len);
 	if (rc < 2 || len > (UINT_MAX >> 2)) {
 		printk(KERN_INFO
 			"bfad[%d]: %s failed to read user buf\n",
 			bfad->inst_no, __func__);
 		kfree(kern_buf);
 		return -EINVAL;
 	}

 	kfree(kern_buf);
 	kfree(bfad->regdata);
 	bfad->regdata = NULL;
 	bfad->reglen = 0;

 	bfad->regdata = kzalloc(len << 2, GFP_KERNEL);
 	if (!bfad->regdata) {
 		printk(KERN_INFO "bfad[%d]: Failed to allocate regrd buffer\n",
 				bfad->inst_no);
 		return -ENOMEM;
 	}

 	bfad->reglen = len << 2;
 	rb = bfa_ioc_bar0(ioc);
 	addr &= BFA_REG_ADDRMSK(ioc);

 	/* offset and len sanity check */
 	rc = bfad_reg_offset_check(bfa, addr, len);
 	if (rc) {
 		printk(KERN_INFO "bfad[%d]: Failed reg offset check\n",
 				bfad->inst_no);
 		kfree(bfad->regdata);
 		bfad->regdata = NULL;
 		bfad->reglen = 0;
 		return -EINVAL;
 	}

 	reg_addr = rb + addr;
 	regbuf =  (u32 *)bfad->regdata;
 	spin_lock_irqsave(&bfad->bfad_lock, flags);
 	for (i = 0; i < len; i++) {
 		*regbuf = readl(reg_addr);
 		regbuf++;
 		reg_addr += sizeof(u32);
 	}
 	spin_unlock_irqrestore(&bfad->bfad_lock, flags);

 	return nbytes;
 }

 static ssize_t
 bfad_debugfs_write_regwr(struct file *file, const char __user *buf,
 		size_t nbytes, loff_t *ppos)
 {
 	struct bfad_debug_info *debug = file->private_data;
 	struct bfad_port_s *port = (struct bfad_port_s *)debug->i_private;
 	struct bfad_s *bfad = port->bfad;
 	struct bfa_s *bfa = &bfad->bfa;
 	struct bfa_ioc_s *ioc = &bfa->ioc;
 	int addr, val, rc;
 	void __iomem *reg_addr;
 	unsigned long flags;
 	void *kern_buf;

-	kern_buf = memdup_user(buf, nbytes);
+	kern_buf = memdup_user_nul(buf, nbytes);
 	if (IS_ERR(kern_buf))
 		return PTR_ERR(kern_buf);

 	rc = sscanf(kern_buf, "%x:%x", &addr, &val);
 	if (rc < 2) {
 		printk(KERN_INFO
 			"bfad[%d]: %s failed to read user buf\n",
 			bfad->inst_no, __func__);
 		kfree(kern_buf);
 		return -EINVAL;
 	}
 	kfree(kern_buf);

 	addr &= BFA_REG_ADDRMSK(ioc); /* offset only 17 bit and word align */

 	/* offset and len sanity check */
 	rc = bfad_reg_offset_check(bfa, addr, 1);
 	if (rc) {
 		printk(KERN_INFO
 			"bfad[%d]: Failed reg offset check\n",
 			bfad->inst_no);
 		return -EINVAL;
 	}

 	reg_addr = (bfa_ioc_bar0(ioc)) + addr;
 	spin_lock_irqsave(&bfad->bfad_lock, flags);
 	writel(val, reg_addr);
 	spin_unlock_irqrestore(&bfad->bfad_lock, flags);

 	return nbytes;
 }



